        if is_listlike(c):
            if len(c) >= 2:
                return (float(c[0]), float(c[1]))
        if isinstance(c, dict):
            if 'x' in c and 'y' in c:
                return (float(c['x']), float(c['y']))
        return (0.0, 0.0)

